export function getUserCameraById(id) {
  return USER_CAMERAS.find((c) => c.id === id) || null;
}

export function getMiddleEastLiveStreams() {
  return USER_CAMERAS.filter((c) => c.stream_type === "iframe" || c.country === "Israel" || c.country === "Lebanon" || c.country === "Middle East");
}

export function getLondonJamCams() {
  return USER_CAMERAS.filter((c) => c.source === "TfL" || c.country === "UK");
}
